from typing import List

class UnionFind:
    def __init__(self, n: int):
        self.parent = list(range(n))
        self.rank = [0] * n
        self.count = n

    def find(self, x: int) -> int:
        # Path compression
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, a: int, b: int):
        rootA = self.find(a)
        rootB = self.find(b)
        if rootA == rootB:
            return
        # Union by rank
        if self.rank[rootA] < self.rank[rootB]:
            self.parent[rootA] = rootB
        elif self.rank[rootA] > self.rank[rootB]:
            self.parent[rootB] = rootA
        else:
            self.parent[rootB] = rootA
            self.rank[rootA] += 1
        self.count -= 1

    def get_count(self) -> int:
        return self.count

def numberOfComponents(properties: List[List[int]], k: int) -> int:
    n = len(properties)
    if n == 0:
        return 0

    uf = UnionFind(n)
    # Convert each property list to a set
    property_sets = [set(lst) for lst in properties]

    for i in range(n):
        for j in range(i + 1, n):
            # Check size of intersection
            if len(property_sets[i] & property_sets[j]) >= k:
                uf.union(i, j)

    return uf.get_count()
